-- Operational (normalised) schema for WealthOps.
-- All data is synthetic and generated by src/wealthops/generate.py.
-- Tables are intentionally narrow and keyed by business identifiers; the
-- analytics layer supplies surrogate keys and conformed dimensions.

CREATE SCHEMA IF NOT EXISTS ops;

CREATE TABLE IF NOT EXISTS ops.channel (
    channel_id      INTEGER PRIMARY KEY,
    channel_code    VARCHAR NOT NULL UNIQUE,
    channel_name    VARCHAR NOT NULL,
    channel_type    VARCHAR NOT NULL
);

-- Scenario expectations written by the pipeline from the generated manifest.
-- Data-quality checks compare observed counts to these values, so a smaller
-- test fixture is still validated against its own declared scenario.
CREATE TABLE IF NOT EXISTS ops.scenario_config (
    key     VARCHAR PRIMARY KEY,
    value   VARCHAR NOT NULL
);

CREATE TABLE IF NOT EXISTS ops.advisor (
    advisor_id          VARCHAR PRIMARY KEY,
    advisor_name        VARCHAR NOT NULL,
    region              VARCHAR NOT NULL,
    segment_specialty   VARCHAR NOT NULL,
    hire_date           DATE NOT NULL,
    status              VARCHAR NOT NULL
);

CREATE TABLE IF NOT EXISTS ops.client (
    client_id       VARCHAR PRIMARY KEY,
    client_name     VARCHAR NOT NULL,
    channel_id      INTEGER NOT NULL REFERENCES ops.channel(channel_id),
    segment         VARCHAR NOT NULL,
    risk_profile    VARCHAR NOT NULL,
    city            VARCHAR NOT NULL,
    onboarding_date DATE NOT NULL,
    status          VARCHAR NOT NULL,
    closed_date     DATE
);

CREATE TABLE IF NOT EXISTS ops.account (
    account_id      VARCHAR PRIMARY KEY,
    client_id       VARCHAR NOT NULL REFERENCES ops.client(client_id),
    account_type    VARCHAR NOT NULL,
    opened_date     DATE NOT NULL,
    status          VARCHAR NOT NULL,
    fee_rate_bps    INTEGER NOT NULL,
    is_fee_based    BOOLEAN NOT NULL
);

-- SCD Type 2 assignment of a client to an advisor.  effective_to is
-- inclusive; NULL means the current interval.  Intervals must not overlap.
CREATE TABLE IF NOT EXISTS ops.advisor_assignment (
    assignment_id       VARCHAR PRIMARY KEY,
    client_id           VARCHAR NOT NULL REFERENCES ops.client(client_id),
    advisor_id          VARCHAR NOT NULL REFERENCES ops.advisor(advisor_id),
    effective_from      DATE NOT NULL,
    effective_to        DATE,
    assignment_reason   VARCHAR NOT NULL,
    is_current          BOOLEAN NOT NULL
);

CREATE TABLE IF NOT EXISTS ops.transaction (
    transaction_id      VARCHAR PRIMARY KEY,
    account_id          VARCHAR NOT NULL REFERENCES ops.account(account_id),
    client_id           VARCHAR NOT NULL REFERENCES ops.client(client_id),
    channel_id          INTEGER NOT NULL REFERENCES ops.channel(channel_id),
    transaction_date    DATE NOT NULL,
    transaction_type    VARCHAR NOT NULL,
    direction           VARCHAR NOT NULL,
    amount_inr          DOUBLE NOT NULL,
    is_net_new          BOOLEAN NOT NULL,
    is_fee_based        BOOLEAN NOT NULL
);

CREATE TABLE IF NOT EXISTS ops.monthly_asset_snapshot (
    snapshot_id             VARCHAR PRIMARY KEY,
    account_id              VARCHAR NOT NULL REFERENCES ops.account(account_id),
    client_id               VARCHAR NOT NULL REFERENCES ops.client(client_id),
    month_end               DATE NOT NULL,
    beginning_assets_inr    DOUBLE NOT NULL,
    market_growth_inr       DOUBLE NOT NULL,
    net_new_assets_inr      DOUBLE NOT NULL,
    internal_income_inr     DOUBLE NOT NULL,
    fee_amount_inr          DOUBLE NOT NULL,
    market_return_pct       DOUBLE NOT NULL,
    market_value_inr        DOUBLE NOT NULL,
    cash_balance_inr        DOUBLE NOT NULL,
    total_assets_inr        DOUBLE NOT NULL
);

CREATE TABLE IF NOT EXISTS ops.engagement_event (
    event_id            VARCHAR PRIMARY KEY,
    client_id           VARCHAR NOT NULL REFERENCES ops.client(client_id),
    advisor_id          VARCHAR NOT NULL REFERENCES ops.advisor(advisor_id),
    channel_id          INTEGER NOT NULL REFERENCES ops.channel(channel_id),
    event_date          DATE NOT NULL,
    event_type          VARCHAR NOT NULL,
    duration_minutes    INTEGER NOT NULL,
    is_planning_event   BOOLEAN NOT NULL
);
